            for u, v in edges:
                qml.IsingZZ(gamma_values[layer], wires=[u, v])
            for wire in wires:
                qml.RX(2 * beta_values[layer], wires=wire)
        return qml.sample(wires=wires)

    return circuit(beta, gamma)

