    """Return 1000 samples from a six-qubit negative-exponent QFT."""
    dev = qml.device("default.qubit", wires=6, shots=1000)

    @qml.qnode(dev)
    def circuit():
        for target in range(6):
            qml.Hadamard(wires=target)
            for control in range(target + 1, 6):
                qml.ControlledPhaseShift(
                    -pi / (2 ** (control - target)),
                    wires=[control, target],
                )
        for wire in range(3):
            qml.SWAP(wires=[wire, 5 - wire])
        return qml.sample()

    return circuit()

