def Deutsch_Jozsa_Balance_4():
    """
    Apply Deutsch-Jozsa to the balanced oracle f(x) = x[0] XOR x[1],
    encoded by "1100", and return 1000 samples of the input register.
    """
    dev = qml.device("default.qubit", wires=5, shots=1000)

    @qml.qnode(dev)
    def circuit():
        qml.PauliX(wires=4)
        for wire in range(5):
            qml.Hadamard(wires=wire)

        for wire, bit in enumerate("1100"):
            if bit == "1":
                qml.CNOT(wires=[wire, 4])

        for wire in range(4):
            qml.Hadamard(wires=wire)

        return qml.sample(wires=range(4))

    return circuit()

