def qpe_grover00_gate(n_count=3):
    """Return 1000 QPE samples using a Grover operator marking |00>."""
    counting = list(range(n_count))
    targets = [n_count, n_count + 1]
    dev = qml.device("default.qubit", wires=n_count + 2, shots=1000)

    def oracle():
        for wire in targets:
            qml.PauliX(wires=wire)
        qml.CZ(wires=targets)
        for wire in targets:
            qml.PauliX(wires=wire)

    def grover():
        oracle()
        for wire in targets:
            qml.Hadamard(wires=wire)
        oracle()
        for wire in targets:
            qml.Hadamard(wires=wire)

    @qml.qnode(dev)
    def circuit():
        for wire in targets:
            qml.Hadamard(wires=wire)
        for wire in counting:
            qml.Hadamard(wires=wire)
        for index, wire in enumerate(counting):
            for _ in range(2 ** (n_count - index - 1)):
                qml.ctrl(grover, control=wire)()
        qml.adjoint(qml.QFT)(wires=counting)
        return qml.sample(wires=counting)

    return circuit()

