def qpe_grover00_gate(n_count=3):
    """Estimate the phase of the complete gate-level Grover search for |00>."""
    count_wires = list(range(n_count))
    target_wires = [n_count, n_count + 1]
    dev = qml.device('default.qubit', wires=n_count + 2, shots=1000)

    def oracle(wires):
        for wire in wires:
            qml.PauliX(wires=wire)
        qml.CZ(wires=wires)
        for wire in wires:
            qml.PauliX(wires=wire)

    def grover_search(wires):
        for wire in wires:
            qml.Hadamard(wires=wire)
        oracle(wires)
        for wire in wires:
            qml.Hadamard(wires=wire)
        oracle(wires)
        for wire in wires:
            qml.Hadamard(wires=wire)

    @qml.qnode(dev)
    def circuit():
        for wire in count_wires:
            qml.Hadamard(wires=wire)
        for index, control in enumerate(count_wires):
            for _ in range(2 ** (n_count - index - 1)):
                qml.ctrl(grover_search, control=control)(target_wires)
        qml.adjoint(qml.QFT)(wires=count_wires)
        return qml.sample(wires=count_wires)

    return circuit()

