            qml.Hadamard(wires=wire)
        for index, control in enumerate(counting):
            for _ in range(2 ** index):
                qml.ctrl(grover, control=control)()
        qml.adjoint(qml.QFT)(wires=counting[::-1])
        return qml.sample(wires=counting)

    return circuit()

