def GHZ3_SWAPTEST():
    """
    Prepare a 3-qubit GHZ state and compare it with |+++> using
    three SWAP-test ancillas. Return 1000 samples of the ancillas.
    """
    dev = qml.device("default.qubit", wires=9, shots=1000)

    @qml.qnode(dev)
    def circuit():
        qml.Hadamard(wires=3)
        qml.CNOT(wires=[3, 4])
        qml.CNOT(wires=[3, 5])

        for wire in range(6, 9):
            qml.Hadamard(wires=wire)

        for ancilla in range(3):
            qml.Hadamard(wires=ancilla)
            qml.CSWAP(wires=[ancilla, ancilla + 3, ancilla + 6])
            qml.Hadamard(wires=ancilla)

        return qml.sample(wires=[0, 1, 2])

    return circuit()

