def GHZ3_SWAPTEST():
    """Return 1000 samples from three independent GHZ3-versus-plus SWAP tests."""
    dev = qml.device("default.qubit", wires=21, shots=1000)

    @qml.qnode(dev)
    def circuit():
        for ancilla in range(3):
            start = 3 + 6 * ancilla
            ghz = [start, start + 1, start + 2]
            plus = [start + 3, start + 4, start + 5]

            qml.Hadamard(wires=ghz[0])
            qml.CNOT(wires=[ghz[0], ghz[1]])
            qml.CNOT(wires=[ghz[0], ghz[2]])
            for wire in plus:
                qml.Hadamard(wires=wire)

            qml.Hadamard(wires=ancilla)
            for left, right in zip(ghz, plus):
                qml.CSWAP(wires=[ancilla, left, right])
            qml.Hadamard(wires=ancilla)

        return qml.sample(wires=[0, 1, 2])

    return circuit()

