import numpy as np


def shor_7mod15():
    """
    Run order finding for 7 modulo 15 using 8 phase qubits and
    4 work qubits. Return 1000 samples of the phase register.
    """
    phase_wires = list(range(8))
    work_wires = list(range(8, 12))
    dev = qml.device("default.qubit", wires=12, shots=1000)

    @qml.qnode(dev)
    def circuit():
        # Initialize the work register to |1>.
        qml.PauliX(wires=work_wires[-1])

        for wire in phase_wires:
            qml.Hadamard(wires=wire)

        for i, wire in enumerate(phase_wires):
            multiplier = pow(7, 2 ** (7 - i), 15)
            unitary = np.zeros((16, 16), dtype=complex)

            for x in range(16):
                y = (multiplier * x) % 15 if x < 15 else 15
                unitary[y, x] = 1

            qml.ctrl(qml.QubitUnitary, control=wire)(
                unitary, wires=work_wires
            )

        qml.adjoint(qml.QFT)(wires=phase_wires)
        return qml.sample(wires=phase_wires)

    return circuit()

import pennylane as qml
import numpy as np

def ipe_t_gate():
    """
    Estimate the T gate phase using 3 IPE iterations.
    Return 1000 samples with bits ordered most significant first.
    """
    dev = qml.device("default.qubit", wires=2, shots=1000)

    @qml.qnode(dev)
    def circuit():
        qml.PauliX(wires=1)
        bits = []

        for iteration in range(3):
            qml.Hadamard(wires=0)

            for _ in range(2 ** (2 - iteration)):
                qml.ctrl(qml.T, control=0)(wires=1)

            for j, bit in enumerate(bits):
                qml.cond(bit, qml.PhaseShift)(
                    -np.pi / 2 ** (iteration - j), wires=0
                )

            qml.Hadamard(wires=0)
            bits.append(qml.measure(0, reset=True))

        return qml.sample(bits[::-1])

    return circuit()

