from scipy.optimize import minimize


def VQE_Z2(param):
    """Run VQE for H = Z(0) Z(1), returning 1000 bit samples."""
    initial = np.asarray(param, dtype=float)
    if initial.shape != (2,):
        raise ValueError('param must contain exactly two initial angles')

    hamiltonian = qml.PauliZ(0) @ qml.PauliZ(1)
    energy_device = qml.device('default.qubit', wires=2)
    sample_device = qml.device('default.qubit', wires=2, shots=1000)

    def ansatz(angles):
        qml.RY(angles[0], wires=0)
        qml.RY(angles[1], wires=1)
        qml.CNOT(wires=[0, 1])

    @qml.qnode(energy_device)
    def energy(angles):
        ansatz(angles)
        return qml.expval(hamiltonian)

    result = minimize(
        lambda angles: float(energy(angles)),
        initial,
        method='Powell',
        options={'maxiter': 300, 'xtol': 1e-9, 'ftol': 1e-9},
    )

    @qml.qnode(sample_device)
    def sample_ground_state(angles):
        ansatz(angles)
        return qml.sample(wires=[0, 1])

    return sample_ground_state(result.x)

