def VQE_Z2(param):
    """Optimize a Z2 parity Hamiltonian and return 1000 basis samples."""
    initial = np.asarray(param, dtype=float).reshape(-1)
    if initial.size == 0:
        raise ValueError('param must contain at least one angle')

    n = initial.size
    wires = list(range(n))
    hamiltonian = qml.PauliZ(0)
    for wire in wires[1:]:
        hamiltonian = hamiltonian @ qml.PauliZ(wire)

    energy_device = qml.device('default.qubit', wires=n)
    sample_device = qml.device('default.qubit', wires=n, shots=1000)

    def ansatz(angles):
        for wire, angle in enumerate(angles):
            qml.RY(angle, wires=wire)
        for wire in range(n - 1):
            qml.CNOT(wires=[wire, wire + 1])

    @qml.qnode(energy_device)
    def energy(angles):
        ansatz(angles)
        return qml.expval(hamiltonian)

    result = minimize(
        lambda angles: float(energy(angles)),
        initial,
        method='Powell',
        options={'maxiter': 300, 'xtol': 1e-9, 'ftol': 1e-9},
    )

    @qml.qnode(sample_device)
    def sample_ground_state(angles):
        ansatz(angles)
        return qml.sample(wires=wires)

    return sample_ground_state(result.x)

import pennylane as qml
import numpy as np


def Toffoli_gate_decompose():
    """Decompose Toffoli into RZ, SX and CX; return 1000 samples."""
    dev = qml.device("default.qubit", wires=3)

    @qml.set_shots(shots=1000)
    @qml.qnode(dev)
    def circuit():
        def hadamard(wire):
            qml.RZ(np.pi / 2, wires=wire)
            qml.SX(wires=wire)
            qml.RZ(np.pi / 2, wires=wire)

        def parity_phase(wires, angle):
            target = wires[-1]
            for control in wires[:-1]:
                qml.CNOT(wires=[control, target])
            qml.RZ(angle, wires=target)
            for control in reversed(wires[:-1]):
                qml.CNOT(wires=[control, target])

        hadamard(2)
        for wire in range(3):
            parity_phase((wire,), np.pi / 4)
        for pair in ((0, 1), (0, 2), (1, 2)):
            parity_phase(pair, -np.pi / 4)
        parity_phase((0, 1, 2), np.pi / 4)
        hadamard(2)
        return qml.sample(wires=[0, 1, 2])

    return np.asarray(circuit())

