import numpy as np
from qiskit.circuit import QuantumCircuit
from qiskit_aer.primitives import Estimator
from qiskit.quantum_info import SparsePauliOp
from scipy.optimize import minimize


def VQE_Z2(param):
    """Return an optimized, unmeasured VQE circuit for H = Z tensor Z."""
    initial = np.asarray(param, dtype=float).reshape(-1)
    if initial.size == 0:
        raise ValueError('param must contain at least one initial angle.')
    if not np.all(np.isfinite(initial)):
        raise ValueError('Initial angles must be finite.')
    if initial.size == 1:
        initial = np.repeat(initial, 2)

    hamiltonian = SparsePauliOp.from_list([('ZZ', 1.0)])
    estimator = Estimator(
        approximation=True,
        run_options={'shots': None},
    )

    def ansatz(theta):
        circuit = QuantumCircuit(2)
        for offset in range(0, len(theta), 2):
            circuit.ry(float(theta[offset]), 0)
            if offset + 1 < len(theta):
                circuit.ry(float(theta[offset + 1]), 1)
            circuit.cx(0, 1)
        return circuit

    def energy(theta):
        result = estimator.run(
            circuits=[ansatz(theta)],
            observables=[hamiltonian],
        ).result()
        return float(np.real(result.values[0]))

    result = minimize(
        energy,
        initial,
        method='Powell',
        options={'xtol': 1e-8, 'ftol': 1e-8, 'maxiter': 1000},
    )
    return ansatz(result.x)

