def qft_6():
    """Apply a six-qubit QFT to a uniform superposition and measure."""
    qubits = cirq.LineQubit.range(6)
    circuit = cirq.Circuit(cirq.H.on_each(*qubits))

    for i in range(6):
        circuit.append(cirq.H(qubits[i]))
        for j in range(i + 1, 6):
            circuit.append(
                cirq.CZPowGate(exponent=1 / (2 ** (j - i))).on(
                    qubits[j], qubits[i]
                )
            )

