import pennylane as qml


def grover_3SAT():
    dev = qml.device("default.qubit", wires=9, shots=1000)
    variables = [2, 1, 0]  # x1, x2, x3
    ancillas = list(range(3, 9))
    clauses = (
        (True, True, True),
        (False, True, True),
        (False, False, False),
        (False, False, True),
        (True, True, False),
        (False, True, False),
    )

    def compute_clauses():
        for clause, ancilla in zip(clauses, ancillas):
            qml.MultiControlledX(
                wires=variables + [ancilla],
                control_values=[0 if positive else 1 for positive in clause],
            )
            qml.PauliX(wires=ancilla)

    @qml.qnode(dev)
    def circuit():
        for wire in variables:
            qml.Hadamard(wires=wire)

        compute_clauses()
        qml.ctrl(qml.PauliZ, control=ancillas[:-1])(wires=ancillas[-1])
        qml.adjoint(compute_clauses)()

        for wire in variables:
            qml.Hadamard(wires=wire)
            qml.PauliX(wires=wire)
        qml.CCZ(wires=variables)
        for wire in variables:
            qml.PauliX(wires=wire)
            qml.Hadamard(wires=wire)

        return qml.sample(wires=[0, 1, 2])

    return circuit()

