            qml.PauliX(wires=wire)
        qml.CZ(wires=target_wires)
        for wire in target_wires:
            qml.PauliX(wires=wire)
            qml.Hadamard(wires=wire)

    @qml.qnode(dev)
    def circuit():
        for wire in target_wires:
            qml.Hadamard(wires=wire)
        for wire in counting_wires:
            qml.Hadamard(wires=wire)

        for index, wire in enumerate(counting_wires):
            for _ in range(2 ** (n_count - index - 1)):
                qml.ctrl(grover, control=wire)()

        qml.adjoint(qml.QFT)(wires=counting_wires)
        return qml.sample(wires=counting_wires)

