def Deutsch_Jozsa_Balance_4() -> QuantumCircuit:
    """Run Deutsch-Jozsa with the balanced oracle mask '1100'."""
    q = QuantumRegister(5, "q")
    c = ClassicalRegister(5, "c")
    circuit = QuantumCircuit(q, c)

    circuit.x(q[4])
    circuit.h(q)

    bitstring = "1100"
    for i, bit in enumerate(bitstring):
        if bit == "1":
            circuit.x(q[i])

    for i in range(4):
        circuit.cx(q[i], q[4])

    for i, bit in enumerate(bitstring):
        if bit == "1":
            circuit.x(q[i])

    circuit.h(q[:4])
    circuit.measure(q, c)
    return circuit

